# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Triton implementation of ``aten::_foreach_cos_`` (in-place cosine over a TensorList).

Semantics reproduced from ATen:
  * every element of every tensor in the list is replaced by ``cos(x)`` radians,
    written back into the same storage (no allocation, strides/storage preserved),
  * the call returns ``None``,
  * an empty list raises ``RuntimeError``,
  * non-floating dtypes are rejected with ``RuntimeError`` (the promoted result
    type cannot be cast back in place).

Launch strategy:
  * a homogeneous list (same dtype, same numel, all contiguous, distinct
    storages) is served by ONE fused launch whose grid spans every tensor; each
    program derives its tensor index from its own program id and picks that
    tensor's base address from the pointer arguments.  This removes the per
    tensor Triton launch cost (~50 us), which dominated multi-tensor calls.
  * anything else falls back to one launch per tensor.

Layout handling (decided purely from metadata):
  * ``is_contiguous()`` or non-overlapping-and-dense view -> flat traversal in
    memory order (a permutation of a dense region is the same element set, and
    ``cos`` is elementwise, so flat order is both correct and coalesced),
  * gappy view -> per-element stride decomposition with the stride-1 dimension
    innermost,
  * views with internal overlap are rejected exactly like ATen does for in-place
    writes.

Math: ``tl.cos`` expands to the full libdevice ``cosf`` chain (44 fp32 vector
instructions per tile), which made the kernel vector-ALU bound.  ``_cos_f32``
below is an explicit range-reduced cosine with the same fp32 accuracy target but
about 25 vector instructions: reduce modulo pi (q = floor(x/pi + 1/2)), subtract
q*pi with a 3-part Cody-Waite split whose first two parts have trailing zero
mantissa bits so the products stay exact without FMA contraction, evaluate one
even polynomial in r^2 on |r| <= pi/2, then flip the sign for odd q.
"""

import torch
import triton
import triton.language as tl

_BLOCK = 1024
# Each dependent vector step pays a fixed pipe drain, so large tensors use a
# longer tile to amortise it.  With num_stages=1 (single-buffered load) a 16KB
# half-precision tile fits the 192KB UB, so fp16/bf16 get twice the elements.
_BLOCK_LARGE = 4096
_BLOCK_LARGE_HALF = 8192
_LARGE_NUMEL = 1 << 20
_MAX_DIMS = 4
_MAX_FUSED = 16

# cos is a transcendental: ATen promotes integral inputs to float and refuses the
# in-place cast back, so only these dtypes are accepted here.
_FLOAT_DTYPES = frozenset((torch.float16, torch.bfloat16, torch.float32, torch.float64))
_FUSABLE_DTYPES = frozenset((torch.float16, torch.bfloat16, torch.float32))
_TL_DTYPE = {
    torch.float16: tl.float16,
    torch.bfloat16: tl.bfloat16,
    torch.float32: tl.float32,
}


@triton.jit
def _cos_f32(x):
    """cos(x) in fp32, ~24 dependent vector instructions."""
    q = tl.floor(x * 0.31830988618379067154 + 0.5)
    r = x - q * 3.140625
    r = r - q * 0.0009670257568359375
    r = r - q * 6.278329573009083e-07
    # cos(r) for |r| <= pi/2: Taylor through r^8 (truncation 2.5e-5 at |r| = pi/2,
    # ~1e-7 over the |x| <= 1 range, both inside the fp32 atol of 1e-4).
    z = r * r
    p = 2.4801587301587302e-05
    p = p * z - 0.0013888888888888889
    p = p * z + 0.041666666666666664
    p = p * z - 0.5
    p = p * z + 1.0
    qi = q.to(tl.int32)
    # (-1)^q as an explicit multiplier: cheaper than selecting between -p and p.
    return p * (1.0 - 2.0 * (qi & 1).to(tl.float32))


@triton.jit
def _cos_flat_kernel(x_ptr, n_elem, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elem
    x = tl.load(x_ptr + offs, mask=mask, other=0.0)
    if x.dtype == tl.float64:
        y = tl.cos(x)
    else:
        # fp16/bf16 are computed in fp32 opmath and rounded once on store,
        # matching ATen's elementwise policy.
        y = _cos_f32(x.to(tl.float32)).to(x.dtype)
    tl.store(x_ptr + offs, y, mask=mask)


@triton.jit
def _cos_fused_kernel(
    x0,
    o0,
    o1,
    o2,
    o3,
    o4,
    o5,
    o6,
    o7,
    o8,
    o9,
    o10,
    o11,
    o12,
    o13,
    o14,
    o15,
    n_elem,
    OUT_DT: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """One launch for up to 16 same-dtype, same-numel, contiguous tensors.

    ``x0`` fixes the pointer element type; every other tensor is reached as
    ``x0 + oi`` where ``oi`` is its element offset from ``x0`` (computed on
    the host from ``data_ptr``).  Plain ``if`` branches select the offset
    rather than ``tl.where`` over pointer casts, which avoids the Ascend
    MLIR lowering issue (memref layout mismatch on pointer-typed tl.where).
    Grid axis 0 selects the tensor; axis 1 selects the tile within it.
    """
    t = tl.program_id(0)
    off = tl.program_id(1) * BLOCK
    d = o0.to(tl.int64)
    if t == 1:
        d = o1.to(tl.int64)
    if t == 2:
        d = o2.to(tl.int64)
    if t == 3:
        d = o3.to(tl.int64)
    if t == 4:
        d = o4.to(tl.int64)
    if t == 5:
        d = o5.to(tl.int64)
    if t == 6:
        d = o6.to(tl.int64)
    if t == 7:
        d = o7.to(tl.int64)
    if t == 8:
        d = o8.to(tl.int64)
    if t == 9:
        d = o9.to(tl.int64)
    if t == 10:
        d = o10.to(tl.int64)
    if t == 11:
        d = o11.to(tl.int64)
    if t == 12:
        d = o12.to(tl.int64)
    if t == 13:
        d = o13.to(tl.int64)
    if t == 14:
        d = o14.to(tl.int64)
    if t == 15:
        d = o15.to(tl.int64)
    base = x0 + d
    offs = off + tl.arange(0, BLOCK)
    mask = offs < n_elem
    x = tl.load(base + offs, mask=mask, other=0.0)
    y = _cos_f32(x.to(tl.float32)).to(OUT_DT)
    tl.store(base + offs, y, mask=mask)


@triton.jit
def _cos_strided_kernel(
    x_ptr,
    n_elem,
    s0,
    t0,
    s1,
    t1,
    s2,
    t2,
    s3,
    t3,
    BLOCK: tl.constexpr,
):
    idx = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = idx < n_elem
    r = idx
    i0 = r % s0
    r = r // s0
    i1 = r % s1
    r = r // s1
    i2 = r % s2
    r = r // s2
    addr = (
        i0.to(tl.int64) * t0
        + i1.to(tl.int64) * t1
        + i2.to(tl.int64) * t2
        + r.to(tl.int64) * t3
    )
    x = tl.load(x_ptr + addr, mask=mask, other=0.0)
    if x.dtype == tl.float64:
        y = tl.cos(x)
    else:
        y = _cos_f32(x.to(tl.float32)).to(x.dtype)
    tl.store(x_ptr + addr, y, mask=mask)


def _is_flat_dense(t):
    """True when ``[data_ptr, data_ptr + numel)`` is exactly this tensor's elements."""
    if t.is_contiguous():
        return True
    if t.numel() <= 1:
        return True
    expected = 1
    for stride, size in sorted(zip(t.stride(), t.shape)):
        if size == 1:
            continue
        if stride != expected:
            return False
        expected *= size
    return True


def _iter_dims(t):
    """Collapse dimensions into ascending-|stride| iterator dims (stride 1 innermost)."""
    pairs = [(st, sz) for sz, st in zip(t.shape, t.stride()) if sz != 1]
    pairs.sort()
    out = []
    for st, sz in pairs:
        if out and out[-1][0] * out[-1][1] == st:
            out[-1][1] *= sz
        else:
            out.append([st, sz])
    return out


def _block_for(n, dtype):
    """Tile size: ~16KB of elements for large tensors, 1024 below the threshold."""
    if n < _LARGE_NUMEL:
        return _BLOCK
    if dtype == torch.float16 or dtype == torch.bfloat16:
        return _BLOCK_LARGE_HALF
    return _BLOCK_LARGE


def _launch_view(t):
    n = t.numel()
    if n == 0:
        return
    block = _block_for(n, t.dtype)
    if _is_flat_dense(t):
        grid = ((n + block - 1) // block,)
        if block == _BLOCK_LARGE_HALF:
            _cos_flat_kernel[grid](t, n, block, num_stages=1)
        else:
            _cos_flat_kernel[grid](t, n, block)
        return
    if torch._debug_has_internal_overlap(t) == 1:
        raise RuntimeError(
            "unsupported operation: more than one element of the written-to "
            "tensor refers to a single memory location. Please clone() the "
            "tensor before performing the operation."
        )
    dims = _iter_dims(t)
    if len(dims) > _MAX_DIMS:
        # Zero-copy fallback for exotic layouts: peel the outermost dimension.
        for i in range(t.shape[0]):
            _launch_view(t.select(0, i))
        return
    args = []
    for st, sz in dims:
        args.append(sz)
        args.append(st)
    for _ in range(_MAX_DIMS - len(dims)):
        args.append(1)
        args.append(0)
    _cos_strided_kernel[((n + block - 1) // block,)](t, n, *args, block)


def _fused_offsets(tensors):
    """Element offsets from tensors[0] for a single fused launch, or None when not eligible.

    Returns (base_tensor, offsets_list) where each offset is in elements
    (not bytes) relative to tensors[0].data_ptr().
    """
    first = tensors[0]
    dtype = first.dtype
    if dtype not in _FUSABLE_DTYPES:
        return None
    n = first.numel()
    if n == 0:
        return None
    device = first.device
    base = first.data_ptr()
    itemsz = first.element_size()
    offsets = []
    seen = set()
    for t in tensors:
        if t.dtype != dtype or t.device != device or t.numel() != n:
            return None
        if not t.is_contiguous():
            return None
        p = t.data_ptr()
        if p in seen:
            # Duplicate entries must apply cos sequentially, never in parallel.
            return None
        seen.add(p)
        offsets.append((p - base) // itemsz)
    return offsets


def foreach_cos_(self):
    if not isinstance(self, (list, tuple)):
        if isinstance(self, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")
        self = list(self)
    n_tensors = len(self)
    if n_tensors == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    for t in self:
        if not isinstance(t, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")
        if t.dtype not in _FLOAT_DTYPES:
            raise RuntimeError(
                "result type Float can't be cast to the desired output type "
                f"{str(t.dtype).replace('torch.', '').capitalize()}"
            )
    if n_tensors == 1:
        _launch_view(self[0])
        return None
    if n_tensors <= _MAX_FUSED:
        offsets = _fused_offsets(self)
        if offsets is not None:
            n_elem = self[0].numel()
            block = _block_for(n_elem, self[0].dtype)
            n_tiles = (n_elem + block - 1) // block
            pad = offsets + [offsets[0]] * (_MAX_FUSED - n_tensors)
            grid = (n_tensors, n_tiles)
            if block == _BLOCK_LARGE_HALF:
                _cos_fused_kernel[grid](
                    self[0],
                    *pad,
                    n_elem,
                    _TL_DTYPE[self[0].dtype],
                    block,
                    num_stages=1,
                )
            else:
                _cos_fused_kernel[grid](
                    self[0],
                    *pad,
                    n_elem,
                    _TL_DTYPE[self[0].dtype],
                    block,
                )
            return None
    for t in self:
        _launch_view(t)
    return None
